const crypto = require('crypto');
const secret = $env.SHOPIFY_WEBHOOK_SECRET || '';
const raw = JSON.stringify($input.item.json.body ?? {});
const sent = $input.item.json.headers?.['x-shopify-hmac-sha256'] || '';
const expected = secret ? crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('base64') : '';
const valid = Boolean(secret) && sent.length === expected.length && crypto.timingSafeEqual(Buffer.from(sent), Buffer.from(expected));
return { json: { ...$input.item.json.body, signatureValid: valid } };
